/**
 * Guard for public/.htaccess, which the production deploy copies into the live site folder.
 *
 * pollardjr.com, www.pollardjr.com and walter.pollardjr.com all serve this one folder, and the two apex names
 * redirect to the portfolio (portfolio.pollardjr.com). The production deploy (.github/workflows/deploy-ssh.yml)
 * moves the live folder aside and uploads a fresh copy, so any .htaccess content that is not in this file is gone
 * after the next deploy. The redirect lives here so it survives that.
 *
 * The block between the markers is generated by buildHtaccess() in the wsp-portfolio repo (scripts/redirects.ts).
 * Change it there first, then paste the new block here. walter.pollardjr.com must never be redirected.
 */

const fs = require('fs');
const path = require('path');

const text = fs.readFileSync(path.join(__dirname, '..', '..', 'public', '.htaccess'), 'utf8');
const BEGIN = '# BEGIN wsp-portfolio-redirects';
const END = '# END wsp-portfolio-redirects';

/** The lines from the BEGIN marker to the END marker, or [] when the block is missing. */
function blockLines() {
  const start = text.indexOf(BEGIN);
  const end = text.indexOf(END);
  if (start === -1 || end <= start) return [];
  return text.slice(start, end + END.length).split(/\r?\n/);
}

describe('public/.htaccess apex redirect block', () => {
  it('is present between its two markers', () => {
    expect(blockLines().length).toBeGreaterThan(2);
  });

  it('puts a host condition directly before every rewrite rule', () => {
    const lines = blockLines();
    const ruleAt = lines.map((line, i) => (line.startsWith('RewriteRule ') ? i : -1)).filter((i) => i !== -1);
    expect(ruleAt).toHaveLength(3);
    for (const i of ruleAt) expect(lines[i - 1]).toMatch(/^RewriteCond %\{HTTP_HOST\} \S+ \[NC\]$/);
  });

  it('matches the two apex names and never walter, the portfolio or staging', () => {
    const conds = blockLines().filter((line) => line.startsWith('RewriteCond '));
    expect(conds).toHaveLength(3);
    for (const cond of conds) {
      const re = new RegExp(cond.split(' ')[2], 'i');
      for (const host of ['pollardjr.com', 'www.pollardjr.com', 'POLLARDJR.COM']) expect(re.test(host)).toBe(true);
      for (const host of ['walter.pollardjr.com', 'portfolio.pollardjr.com', 'staging-portfolio.pollardjr.com', 'evilpollardjr.com', 'pollardjr.com.example.org']) {
        expect(re.test(host)).toBe(false);
      }
    }
  });

  it('sends the apex home page to the portfolio and /timeline and /blog to walter', () => {
    const rules = blockLines().filter((line) => line.startsWith('RewriteRule '));
    expect(rules).toEqual([
      'RewriteRule ^$ https://portfolio.pollardjr.com/ [R=301,L]',
      'RewriteRule ^timeline/?$ https://walter.pollardjr.com/timeline/ [R=301,L]',
      'RewriteRule ^blog(/.*)?$ https://walter.pollardjr.com/blog$1 [R=301,L]',
    ]);
  });
});

describe('public/.htaccess MIME override', () => {
  it('still forces image/png on the extension-less opengraph-image file', () => {
    expect(text).toMatch(/<Files "opengraph-image">\s+ForceType image\/png\s+<\/Files>/);
  });
});
